import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
experiment_data = np.load(
    os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
).item()

for dataset_name, ds in experiment_data.items():
    print(f"\n=== Dataset: {dataset_name} ===")

    probe_auroc = ds.get("probe_auroc", {})
    if probe_auroc:
        # Best overall probe
        best_key = max(probe_auroc, key=lambda k: probe_auroc[k])
        print(f"Best probe ({best_key}) validation AUROC: {probe_auroc[best_key]:.4f}")

        # Best group-aggregated probe (excludes per-agent probes)
        group_items = {
            k: v
            for k, v in probe_auroc.items()
            if k.startswith(("mean_", "max_", "min_", "var_", "concat_"))
        }
        if group_items:
            bg_key = max(group_items, key=lambda k: group_items[k])
            print(
                f"Best group-aggregated probe ({bg_key}) validation AUROC: {group_items[bg_key]:.4f}"
            )

        # Best per-agent probe
        agent_items = {k: v for k, v in probe_auroc.items() if k.startswith("agent")}
        if agent_items:
            ba_key = max(agent_items, key=lambda k: agent_items[k])
            print(
                f"Best per-agent probe ({ba_key}) validation AUROC: {agent_items[ba_key]:.4f}"
            )

        # Baselines
        if "text_tfidf" in probe_auroc:
            print(
                f"Text TF-IDF baseline validation AUROC: {probe_auroc['text_tfidf']:.4f}"
            )
        if "random_features" in probe_auroc:
            print(
                f"Random features control validation AUROC: {probe_auroc['random_features']:.4f}"
            )

        # Print all probe AUROCs
        print("\nAll probe validation AUROC values:")
        for k, v in sorted(probe_auroc.items(), key=lambda x: -x[1]):
            print(f"  {k}: {v:.4f}")

    per_domain = ds.get("per_domain_auroc", {})
    if per_domain:
        valid_vals = [
            v for v in per_domain.values() if not (isinstance(v, float) and np.isnan(v))
        ]
        if valid_vals:
            print(f"\nMean per-domain validation AUROC: {np.mean(valid_vals):.4f}")
            best_dom = max(
                per_domain,
                key=lambda d: (per_domain[d] if not np.isnan(per_domain[d]) else -1),
            )
            worst_dom = min(
                per_domain,
                key=lambda d: (per_domain[d] if not np.isnan(per_domain[d]) else 2),
            )
            print(
                f"Best domain ({best_dom}) validation AUROC: {per_domain[best_dom]:.4f}"
            )
            print(
                f"Worst domain ({worst_dom}) validation AUROC: {per_domain[worst_dom]:.4f}"
            )

        print("\nPer-domain validation AUROC values:")
        for d, v in per_domain.items():
            if isinstance(v, float) and np.isnan(v):
                print(f"  {d}: nan")
            else:
                print(f"  {d}: {v:.4f}")

    losses = ds.get("losses", {})
    if losses.get("train"):
        print(f"\nFinal training loss: {losses['train'][-1]:.4f}")
    if losses.get("val"):
        print(f"Final validation loss: {losses['val'][-1]:.4f}")
