            print(f"{probe_name} - std across folds AUROC: {np.std(folds):.4f}")

    # Best overall probe
    if agg_auroc:
        best_probe = max(agg_auroc, key=agg_auroc.get)
        print(f"\nBest probe by mean AUROC: {best_probe}")
        print(f"Best probe mean 5-fold CV AUROC: {agg_auroc[best_probe]:.4f}")

    # Best group-aggregated (matches primary metric in original code)
    group_probes = ["group_mean_pool", "group_max_pool", "group_concat"]
