        print(f"Final recorded validation loss (1 - AUROC): {val_losses[-1]:.4f}")
        print(f"Minimum recorded validation loss (1 - AUROC): {min(val_losses):.4f}")

    # Notes
    notes = data.get("notes", [])
    if notes:
        print("Notes:")
        for n in notes:
            print(f"  - {n}")

    # Ground truth class balance
    gt = data.get("ground_truth", [])
    if len(gt) > 0:
        gt_arr = np.array(gt)
        print(f"Ground truth - number of colluding samples: {int(gt_arr.sum())}")
        print(f"Ground truth - number of honest samples: {int((1 - gt_arr).sum())}")
